   if(id===1){markup='<h2>Frame the evidence question</h2><p class="small">A fictional museum café needs a staffing decision. Edit the five ingredients. Build a question that a dataset could help answer.</p><div class="experiment-grid"><div class="workspace"><div class="controls">'+[['stakeholder','Stakeholder'],['decision','Pending decision'],['population','Eligible population'],['measure','Observable measure'],['period','Decision horizon']].map(function(p){return '<label for="q-'+p[0]+'">'+p[1]+'<input id="q-'+p[0]+'" type="text" maxlength="180" value="'+esc(a[p[0]])+'"></label>';}).join('')+'</div><button class="primary" id="build-question" style="margin-top:18px">Build my question</button><div class="insight" id="question-output" aria-live="polite">Name the decision and evidence before choosing software.</div></div>'+predictBox(id,'What could evidence clarify?',['Name the person making the decision.','Choose a population and a period.','Keep your question neutral about the result.'])+'</div>';}
